package stemmate.server;

import com.sun.net.httpserver.*;
import java.io.*;
import java.net.*;
import java.nio.charset.StandardCharsets;
import java.util.*;
import static stemmate.server.TestHarness.*;

/** Tests validation, codecs and route dispatch without opening network sockets or a database. */
public final class Role7ServerTests {
    static Map<String,String> valid(){return new LinkedHashMap<>(Map.of("planId","synthetic-plan","title","Synthetic plan","safety","No drinking water","activityId","ACT-101","updatedAt","1793991600000","targetGroup","Grade 7","inclusion","Picture cards","steps","Build a filter","timing","30","materials","Bottle"));}
    static TestCase tc(String id,String title,String req,String component,String steps,String expected,String kind,Check check){return new TestCase(id,title,req,component,steps,expected,kind,check);}
    static List<TestCase> cases(){List<TestCase> tests=new ArrayList<>();
        tests.add(tc("S01","Server accepts a valid synthetic plan","FR3, FR4","Validator.checkPlan","Validate a synthetic plan with required content and valid identifiers.","No validation problems.","Server validation unit",()->{List<String> p=Validator.checkPlan(valid());observe("problems="+p);equal(List.of(),p,"Valid plan");}));
        tests.add(tc("S02","Server rejects blank identity title and safety","FR3, FR4","Validator.checkPlan","Remove planId, blank title and blank safety.","All three required-field problems are returned.","Server validation unit",()->{Map<String,String> p=valid();p.remove("planId");p.put("title"," ");p.put("safety"," ");List<String> errors=Validator.checkPlan(p);observe(errors.toString());equal(3,errors.size(),"Required-field problem count");}));
        tests.add(tc("S03","Server enforces the 120 character title limit","FR3","Validator.checkPlan","Validate title lengths of 120 and 121.","120 is accepted; 121 is rejected.","Server validation boundary",()->{Map<String,String> p=valid();p.put("title","A".repeat(120));equal(0,Validator.checkPlan(p).size(),"120 characters");p.put("title","A".repeat(121));require(Validator.checkPlan(p).stream().anyMatch(x->x.contains("too long")),"121 not rejected");observe("120 accepted; 121 rejected");}));
        tests.add(tc("S04","Server rejects invalid update timestamps","FR5","Validator.checkPlan","Try a negative value, alphabetic value and sixteen digits.","Each invalid timestamp is rejected.","Server validation boundary",()->{for(String x:List.of("-1","tomorrow","1234567890123456")){Map<String,String> p=valid();p.put("updatedAt",x);require(Validator.checkPlan(p).stream().anyMatch(e->e.contains("updatedAt")),"Timestamp accepted: "+x);}observe("three invalid timestamp values rejected");}));
        tests.add(tc("S05","Server rejects a malformed activity ID","FR3","Validator.checkPlan","Replace ACT-101 with a UUID-shaped desktop activity ID.","The current server contract rejects the incompatible format.","Server validation contract",()->{Map<String,String> p=valid();p.put("activityId","10000000-0000-0000-0000-000000000001");List<String> errors=Validator.checkPlan(p);observe(errors.toString());require(errors.stream().anyMatch(x->x.contains("ACT-101")),"UUID activity format should be rejected by current contract");}));
        tests.add(tc("S06","Server checks every FR4 element","FR4","Validator.checkPlan","Remove steps, timing, materials and inclusion, keeping title and safety.","An incomplete FR4 plan is rejected.","Server requirements negative test",()->{Map<String,String> p=valid();for(String k:List.of("steps","timing","materials","inclusion"))p.remove(k);List<String> errors=Validator.checkPlan(p);observe("missing four FR4 elements; validation problems="+errors);require(!errors.isEmpty(),"Server accepts a plan missing steps, timing, materials and inclusion");}));
        tests.add(tc("S07","Server line codec preserves special characters","FR3, FR5","Server.encode and Server.decode","Round-trip ampersands, equals, spaces, quotes and a non-ASCII character.","Every field is preserved exactly.","Codec unit",()->{Map<String,String> p=Map.of("title","Water & light = safe \"demo\"","note","Windhoek café");String line=Server.encode(p);equal(p,Server.decode(line),"Line codec round trip");observe("encoded="+line); }));
        tests.add(tc("S08","Health route returns its documented status","SUS1","Server.handle GET /health","Dispatch an in-memory HTTP exchange to the production route handler.","HTTP 200 and status=OK.","Route component with HttpExchange double",()->{Exchange x=new Exchange("GET","/health","");Server.handle(x);observe("status="+x.code+"; body="+x.text());equal(200,x.code,"Health HTTP status");equal("status=OK",x.text(),"Health body");}));
        tests.add(tc("S09","Sync route rejects invalid device ID","FR5","Server.handleSync","Dispatch POST /sync with an invalid device identifier.","HTTP 400 before any database operation.","Route validation with HttpExchange double",()->{Exchange x=new Exchange("POST","/sync?deviceId=bad%20id","");Server.handle(x);observe("status="+x.code+"; body="+x.text());equal(400,x.code,"Invalid device HTTP status");}));
        tests.add(tc("S10","Sync route rejects an oversized body","QR2","Server.handleSync","Send MAX_BODY_BYTES plus one byte through an in-memory exchange.","HTTP 400 before database access.","Route boundary with HttpExchange double",()->{Exchange x=new Exchange("POST","/sync?deviceId=test-device","x".repeat(Server.MAX_BODY_BYTES+1));Server.handle(x);observe("status="+x.code+"; body="+x.text());equal(400,x.code,"Oversized body HTTP status");require(x.text().contains("Too+much+data"),"Size error message");}));
        tests.add(tc("S11","Java server supports the desktop upload route","FR5","HttpRemoteSessionPlanStore and Server.handle","Dispatch the POST /plans route used by client/App.java to the supplied Java server.","The desktop upload route is supported rather than returning 404.","Cross-component route compatibility audit",()->{Exchange x=new Exchange("POST","/plans","{\"plans\":[]}");Server.handle(x);observe("desktop uses POST /plans; Java server returned "+x.code+"; "+x.text());require(x.code!=404,"Desktop client POST /plans is unsupported by the supplied Java server; prototype/src uses a different /sync protocol");}));
        return tests;
    }
    public static void main(String[] args)throws Exception{TestHarness.run(Role7ServerTests.class.getName(),args,cases());}
    static final class Exchange extends HttpExchange {
        final String method;final URI uri;InputStream input;OutputStream output;final ByteArrayOutputStream body=new ByteArrayOutputStream();final Headers requestHeaders=new Headers(),responseHeaders=new Headers();int code=-1;
        Exchange(String method,String uri,String text){this.method=method;this.uri=URI.create(uri);input=new ByteArrayInputStream(text.getBytes(StandardCharsets.UTF_8));output=body;}
        String text(){return body.toString(StandardCharsets.UTF_8);}public Headers getRequestHeaders(){return requestHeaders;}public Headers getResponseHeaders(){return responseHeaders;}
        public URI getRequestURI(){return uri;}public String getRequestMethod(){return method;}public HttpContext getHttpContext(){return null;}public void close(){}
        public InputStream getRequestBody(){return input;}public OutputStream getResponseBody(){return output;}public void sendResponseHeaders(int c,long length){code=c;}
        public InetSocketAddress getRemoteAddress(){return new InetSocketAddress("127.0.0.1",12345);}public int getResponseCode(){return code;}public InetSocketAddress getLocalAddress(){return new InetSocketAddress("127.0.0.1",8080);}public String getProtocol(){return "HTTP/1.1";}
        public Object getAttribute(String name){return null;}public void setAttribute(String name,Object value){}public void setStreams(InputStream in,OutputStream out){input=in;output=out;}public HttpPrincipal getPrincipal(){return null;}
    }
}
